   JSONObject pending=v.transferIn();if(pending==null)throw new SecurityException("Enter the transfer words again.");byte[] key=Crypto.unb64(pending.getString("historyKey"));try{if(!resumeMove){pending.put("includeHistory",history!=null);v.transferIn(pending);}if(pending.optBoolean("includeHistory")&&!pending.optBoolean("historySaved")&&history==null)throw new SecurityException("Choose the encrypted chats file again before finishing. The old phone keeps its copy until then.");if(history!=null)Vault.verifyTransfer(history,key,pending.getJSONObject("profile"));AccountTransfer.accept(v,pass);if(history!=null){v.importTransfer(history,key);v.historySaved();}AccountTransfer.finishReceive(v);}finally{Arrays.fill(key,(byte)0);}return true;
